import { useForm, SubmitHandler } from "react-hook-form";
import { BlutilsResult } from "@/types/BlutilsResult";
import { Button, Spinner } from "flowbite-react";
import { HiOutlineUpload } from "react-icons/hi";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";

/**
 * Sample dataset: the ZymoBIOMICS mock ITS run classified with the relaxed
 * strategy, as in the blutils benchmark (blutils-benchmarks
 * output/blutils/ITS/relaxed.json). Served with the app from public/examples;
 * absolute so that `?p=` keeps it across reloads like any other URL.
 */
export const EXAMPLE_RESULT_PATH = "/examples/zymo-its-relaxed.json";

export function exampleResultUrl(): string {
  return new URL(`${process.env.PUBLIC_URL}${EXAMPLE_RESULT_PATH}`, window.location.origin).href;
}

const INVALID_FILE_MESSAGE =
  "That file isn't a valid Blutils result. Make sure it's the blutils.consensus.json your run produced.";

function parseBlutilsResult(text: string): BlutilsResult {
  const parsed: unknown = JSON.parse(text);
  if (
    typeof parsed !== "object" ||
    parsed === null ||
    !Array.isArray((parsed as { results?: unknown }).results)
  ) {
    throw new Error("Not a Blutils result");
  }
  return parsed as BlutilsResult;
}

interface IFormInput {
  content: FileList;
}

interface Props {
  resultSetter: (result: BlutilsResult) => void;
}

export function ResultLoader({ resultSetter }: Props) {
  const [isLoading, setIsLoading] = useState(false);
  const [fileName, setFileName] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [searchParams, setSearchParams] = useSearchParams();
  const { register, handleSubmit } = useForm<IFormInput>();
  const fileField = register("content");
  const loadedPath = useRef<string | null>(null);

  // Keep the other params (`?v=`, `?g=`) so a shared deep link survives the load.
  const setPathParam = useCallback(
    (path: string) =>
      setSearchParams((prev) => {
        const params = new URLSearchParams(prev);
        params.set("p", path);
        return params;
      }),
    [setSearchParams]
  );

  const urlIsValid = (urlString: string | null) => {
    try {
      if (!urlString) return false;
      return Boolean(new URL(urlString));
    } catch (_) {
      return false;
    }
  };

  const memoizedUrlState = useMemo(() => {
    if (searchParams.has("p")) {
      const p = searchParams.get("p");
      if (urlIsValid(p)) return p as string;
    }

    return null;
  }, [searchParams]);

  /**
   * Fetches a result file from a URL (the sample dataset or a `?p=` URL).
   */
  const handleLoadFromPath = useCallback(
    (path: string) => {
      loadedPath.current = path;
      setIsLoading(true);
      setError(null);

      fetch(path)
        .then((response) => {
          if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
          }
          return response.text();
        })
        .then(
          (text) => {
            let parsed: BlutilsResult;
            try {
              parsed = parseBlutilsResult(text);
            } catch (_) {
              // A body that was fetched but is not a Blutils result gets the
              // same message as an invalid upload.
              setError(INVALID_FILE_MESSAGE);
              return;
            }
            resultSetter(parsed);
            setPathParam(path);
          },
          () =>
            setError(
              path === exampleResultUrl()
                ? "Couldn't load the sample dataset. Please try again."
                : "Couldn't load the result file. Check the URL and try again."
            )
        )
        .finally(() => setIsLoading(false));
    },
    [resultSetter, setPathParam]
  );

  useEffect(() => {
    // setSearchParams after a load changes `handleLoadFromPath`; skip the path
    // that was already loaded so it is not fetched twice.
    if (memoizedUrlState && memoizedUrlState !== loadedPath.current) {
      handleLoadFromPath(memoizedUrlState);
    }
  }, [memoizedUrlState, handleLoadFromPath]);

  const onSubmit: SubmitHandler<IFormInput> = async ({ content }: IFormInput) => {
    const targetFile = content?.item(0);
    if (!targetFile) return;

    try {
      const fileContent = await targetFile.text();
      const parsed = parseBlutilsResult(fileContent);
      setError(null);
      setPathParam(targetFile.name);
      resultSetter(parsed);
    } catch (e) {
      setError(INVALID_FILE_MESSAGE);
    }
  };

  return (
    <div className="m-auto my-24 flex w-full max-w-lg flex-col gap-8 rounded-xl border border-gray-200 bg-surface p-8 shadow-sm dark:border-gray-700 dark:bg-surface-dark">
      <header className="text-center">
        <h1 className="text-2xl font-bold tracking-tight text-ink dark:text-gray-100">
          Open your results
        </h1>
        <p className="mt-2 text-sm text-gray-600 dark:text-gray-400">
          Load the <code className="text-[0.8em]">blutils.consensus.json</code>{" "}
          your Blutils run produced to explore the taxonomic consensus.
        </p>
      </header>

      <form onSubmit={handleSubmit(onSubmit)} className="flex flex-col gap-4">
        <div className="relative">
          <input
            id="file"
            type="file"
            accept=".json,application/json"
            className="peer sr-only"
            {...fileField}
            onChange={(e) => {
              fileField.onChange(e);
              setError(null);
              setFileName(e.target.files?.[0]?.name ?? null);
            }}
          />
          <label
            htmlFor="file"
            className="flex cursor-pointer flex-col items-center justify-center gap-1 rounded-lg border-2 border-dashed border-gray-300 bg-gray-50 px-6 py-8 text-center transition-colors hover:border-gray-400 hover:bg-gray-50 peer-focus-visible:border-gray-500 peer-focus-visible:ring-2 peer-focus-visible:ring-gray-300 dark:border-gray-600 dark:bg-gray-800/50 dark:hover:border-gray-500 dark:hover:bg-gray-800"
          >
            <HiOutlineUpload className="mb-1 h-7 w-7 text-gray-400 dark:text-gray-500" />
            <span className="text-sm font-medium text-ink dark:text-gray-100">
              {fileName ?? "Choose your result file"}
            </span>
            <span className="text-xs text-gray-600 dark:text-gray-400">
              {fileName ? "Click to choose a different file" : "blutils.consensus.json from your run"}
            </span>
          </label>
        </div>

        {error && (
          <p role="alert" className="text-sm text-red-600 dark:text-red-400">
            {error}
          </p>
        )}

        <Button type="submit" fullSized disabled={!fileName}>
          View results
        </Button>
      </form>

      <div className="border-t border-gray-200 pt-5 text-center dark:border-gray-700">
        <p className="text-sm text-gray-600 dark:text-gray-400">
          New to Blutils?{" "}
          <button
            type="button"
            onClick={() => handleLoadFromPath(exampleResultUrl())}
            disabled={isLoading}
            className="font-medium text-gray-700 underline decoration-dotted underline-offset-2 hover:text-gray-900 disabled:opacity-60 dark:text-gray-300 dark:hover:text-white"
          >
            Load a sample dataset
          </button>{" "}
          <span className="text-xs text-gray-500 dark:text-gray-400">
            (ZymoBIOMICS mock, ITS, relaxed)
          </span>
          {isLoading && <Spinner size="sm" className="ml-2 align-middle" />}
        </p>
      </div>
    </div>
  );
}
